async function loadBackdrop(){const targetBackdrop=backdrop,targetTheme=state.theme;const name={tidal:'tidal',opal:'opal',moss:'moss',obsidian:'obsidian',aurora:'aurora',amber:'amber'}[state.theme];const path=`assets/artwork/background-${name}.png`;try{const res=await fetch(path,{method:'HEAD'});if(!res.ok)return;const tex=await new THREE.TextureLoader().loadAsync(path);tex.colorSpace=THREE.SRGBColorSpace;if(backdrop!==targetBackdrop||state.theme!==targetTheme){tex.dispose();return;}if(backdrop.material.map)backdrop.material.map.dispose();backdrop.material.map=tex;backdrop.material.color.set(0x7899b8);backdrop.material.needsUpdate=true;backdrop.visible=true;}catch(e){/* The geometric abstract environment is complete without a backplate. */}}

function disposeGeometries(group){const shared=new Set(Object.values(materials||{})),geometries=new Set(),ownedMaterials=new Set(),textures=new Set();group.traverse(o=>{if(o.isReflector)o.getRenderTarget().dispose();if(o.geometry)geometries.add(o.geometry);for(const mat of(Array.isArray(o.material)?o.material:o.material?[o.material]:[])){if(!shared.has(mat)){ownedMaterials.add(mat);if(mat.map)textures.add(mat.map);}}});geometries.forEach(g=>g.dispose());ownedMaterials.forEach(m=>m.dispose());textures.forEach(t=>t.dispose());}
