  const instanceMaterials=options.material&&materials[options.material]?{...materials,gel:materials[options.material]}:materials;const group=createElement(id,instanceMaterials,options);group.position.fromArray(position);group.rotation.fromArray(rotation);if(Array.isArray(scale))group.scale.multiply(new THREE.Vector3(...scale));else group.scale.multiplyScalar(scale);group.userData.elementId=id;
  group.traverse(mesh=>{if(mesh.isMesh){mesh.castShadow=true;mesh.receiveShadow=true;mesh.userData.elementRoot=group;pickables.push(mesh);}});content.add(group);const motion=new MotionController(group,{id,onChange:v=>{$('#interaction-state').textContent=`VALUE ${Math.round(v*100)}%`;bus.emit('change',group.position,1,{value:v});}});motions.push(motion);group.userData.motionController=motion;return group;
